'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { ArrowRight, ChevronLeft, X } from 'lucide-react';
import { OnboardingProgress } from './OnboardingProgress';
import { StylePreference } from '@/lib/types/user-profile-types';
import useEmblaCarousel from 'embla-carousel-react';

interface OnboardingStyleProps {
  onNext: (styles: StylePreference[]) => void;
  onBack: () => void;
}

const styleOptions: StylePreference[] = [
  {
    id: 'minimal',
    name: 'Minimal',
    description: 'Timeless',
    longDescription: 'Less is more, clean, simple, neutral palette, pieces that last forever',
    imageUrl: '/images/styles/Group 31.png',
  },
  {
    id: 'luxury',
    name: 'Luxury',
    description: 'Elegant',
    longDescription: 'Less is more, clean, simple, neutral palette, pieces that last forever',
    imageUrl: '/images/styles/Group 32.png',
  },
  {
    id: 'eccentric',
    name: 'Eccentric',
    description: 'Creative',
    longDescription: 'Highly artistic and individual; uses unique shapes, bold colors, and clashing patterns and playful',
    imageUrl: '/images/styles/Group 33.png',
  },
  {
    id: 'business',
    name: 'Business',
    description: 'Refined',
    longDescription: 'Smart, structured, and professional',
    imageUrl: '/images/styles/Group 34.png',
  },
  {
    id: 'vanilla',
    name: 'Vanilla',
    description: 'Clean',
    longDescription: 'Soft neutrals, fresh, and cozy in light tones',
    imageUrl: '/images/styles/Group 35.png',
  },
  {
    id: 'sporty',
    name: 'Sporty',
    description: 'Active',
    longDescription: 'Athletic wear, functional, ready for movement and confident',
    imageUrl: '/images/styles/Group 36.png',
  },
  {
    id: 'edgy',
    name: 'Edgy',
    description: 'Trendy',
    longDescription: 'Bold, modern, and daring; follows the very latest fashion trends',
    imageUrl: '/images/styles/Group 37.png',
  },
  {
    id: 'bohemian',
    name: 'Bohemian',
    description: 'Natural',
    longDescription: 'Relaxed, earthy, featuring flowly silhouettes and natural fabrics',
    imageUrl: '/images/styles/Group 38.png',
  },
  {
    id: 'classic',
    name: 'Classic',
    description: 'Old Money',
    longDescription: 'Understated quiet luxury built on timeless, tailored, and preppy pieces',
    imageUrl: '/images/styles/Group 39.png',
  },
  {
    id: 'mystery',
    name: 'Mystery Style',
    description: 'Random style',
    longDescription: 'Random style',
    imageUrl: '/images/styles/Group 40.png',
  },
];

export function OnboardingStyle({ onNext, onBack }: OnboardingStyleProps) {
  const [selectedStyles, setSelectedStyles] = useState<StylePreference[]>([]);
  const [failedImages, setFailedImages] = useState<Set<string>>(new Set());
  const [emblaRef] = useEmblaCarousel({
    align: 'start',
    containScroll: 'trimSnaps',
  });

  const handleImageError = (styleId: string) => {
    setFailedImages((prev) => new Set(prev).add(styleId));
  };

  const toggleStyle = (style: StylePreference) => {
    setSelectedStyles((prev) => {
      const isSelected = prev.some((s) => s.id === style.id);
      if (isSelected) {
        return prev.filter((s) => s.id !== style.id);
      } else {
        return [...prev, style];
      }
    });
  };

  const removeStyle = (styleId: string) => {
    setSelectedStyles((prev) => prev.filter((s) => s.id !== styleId));
  };

  const handleNext = () => {
    if (selectedStyles.length > 0) {
      onNext(selectedStyles);
    }
  };

  return (
    <div className="flex flex-col min-h-screen bg-[var(--onboarding-bg)]">
      {/* Back Button */}
      <div className="p-4">
        <Button
          variant="ghost"
          onClick={onBack}
          className="text-gray-600 hover:text-gray-900"
        >
          <ChevronLeft className="w-5 h-5" />
        </Button>
      </div>

      {/* Progress */}
      <OnboardingProgress currentStep={5} totalSteps={7} />

      {/* Content */}
      <div className="flex-1 flex flex-col p-6">
        <div className="max-w-4xl w-full mx-auto space-y-6">
          {/* Heading */}
          <div className="text-center space-y-2">
            <h1 className="text-3xl font-bold text-gray-900">
              What&apos;s your style?
            </h1>
            <p className="text-lg text-gray-600">
              Choose style that sparks you
            </p>
          </div>

          {/* Selected Styles Thumbnails */}
          {selectedStyles.length > 0 && (
            <div className="flex gap-3 overflow-x-auto pb-2 justify-center">
              {selectedStyles.map((style) => (
                <div
                  key={style.id}
                  className="relative flex-shrink-0 w-[60px] h-[80px] rounded-lg overflow-hidden border-2 border-[var(--onboarding-primary)]"
                >
                  <img
                    src={style.imageUrl || '/images/styles/Group 40.png'}
                    alt={`${style.name} style`}
                    className="w-full h-full object-cover"
                  />
                  <button
                    onClick={() => removeStyle(style.id)}
                    className="absolute top-1 right-1 w-5 h-5 bg-[var(--onboarding-primary)] rounded-full flex items-center justify-center shadow-sm"
                  >
                    <X className="w-3 h-3 text-white" />
                  </button>
                </div>
              ))}
            </div>
          )}

          {/* Carousel */}
          <div className="overflow-hidden" ref={emblaRef}>
            <div className="flex gap-4">
              {styleOptions.map((style) => {
                const isSelected = selectedStyles.some((s) => s.id === style.id);
                return (
                  <div
                    key={style.id}
                    className="flex-[0_0_280px] min-w-0"
                  >
                    <button
                      onClick={() => toggleStyle(style)}
                      className={`
                        w-full h-80 rounded-2xl p-6 flex flex-col items-center justify-center
                        transition-all duration-300 border-4
                        ${
                          isSelected
                            ? 'border-[var(--onboarding-primary)] bg-white'
                            : 'border-gray-200 bg-white hover:border-gray-300'
                        }
                      `}
                    >
                      {/* Style Image */}
                      <div className="w-full h-48 rounded-xl mb-4 overflow-hidden">
                        {style.imageUrl && !failedImages.has(style.id) ? (
                          <img
                            src={style.imageUrl}
                            alt={`${style.name} style`}
                            loading="lazy"
                            onError={() => handleImageError(style.id)}
                            className="w-full h-full object-cover"
                          />
                        ) : (
                          <div className="w-full h-full bg-gradient-to-br from-gray-100 to-gray-200 flex items-center justify-center">
                            <span className="text-4xl">👗</span>
                          </div>
                        )}
                      </div>

                      {/* Style Name */}
                      <h3 className="text-xl font-bold text-[var(--onboarding-primary)]">
                        {style.name} · {style.description}
                      </h3>
                      {style.longDescription && (
                        <p className="text-sm text-gray-500 text-center mt-1 px-2">
                          {style.longDescription}
                        </p>
                      )}

                      {/* Selected Badge */}
                      {isSelected && (
                        <div className="mt-3 bg-[var(--onboarding-primary)] text-white px-3 py-1 rounded-full text-xs font-semibold">
                          Selected
                        </div>
                      )}
                    </button>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Next Button */}
          <div className="flex justify-end">
            <Button
              onClick={handleNext}
              disabled={selectedStyles.length === 0}
              className="w-14 h-14 rounded-full bg-[var(--onboarding-primary)] hover:bg-[var(--onboarding-primary-hover)] text-white disabled:bg-gray-300 disabled:cursor-not-allowed"
            >
              <ArrowRight className="w-6 h-6" />
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

